let governedToken='';
function governedPage(){return heading('Governed agent service','Scholarion Academy · Local server pilot')+`<section class="card prose"><p>This workspace uses separate local tenant databases and server-checked account sessions. It is an extractive study helper, not a live AI model or production identity provider.</p>${location.port!=='4180'?'<p><a class="button" href="http://127.0.0.1:4180/#governed-agent">Open the local service</a></p>':''}<p>Sign in with your username, password and authenticator code.</p><form id="governed-question"><label>Study question<textarea name="question" maxlength="4000" required placeholder="How should I compare a workflow with a baseline?"></textarea></label><button class="button">Ask using approved sources</button></form><div id="governed-answer" role="status" style="white-space:pre-wrap"></div></section><section class="card prose"><h2>Educator draft review</h2><p>AI DRAFT — REQUIRES HUMAN EDUCATOR REVIEW &amp; PUBLISHING. This pilot stores educator-authored drafts. Approval records a review; it does not publish content or post grades.</p><form id="governed-draft"><label>Draft for review<textarea name="body" required maxlength="5000"></textarea></label><button class="button secondary">Save draft</button></form><button class="button secondary" data-governed-list>Refresh drafts</button><button class="button secondary" data-governed-audit>View audit events</button><div id="governed-records" aria-live="polite"></div></section>`;}
async function governedApi(action,payload={}){if(location.port!=='4180')throw Error('Open the local service on port 4180 first.');const r=await fetch('/api/governed/'+action,{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+governedToken},body:JSON.stringify({tenant:'scholarion',course:'AIM310',...payload})});const data=await r.json();if(!r.ok)throw Error(data.error||'Request failed');return data;}
function governedDrafts(rows){document.getElementById('governed-records').innerHTML=rows.map(r=>`<article class="callout"><p>${esc(r.body)}</p><p>${esc(r.state)} · version ${r.version}</p>${r.state==='draft'?`<button class="button secondary" data-governed-approve="${esc(r.id)}" data-version="${r.version}">Approve review record</button>`:''}</article>`).join('')||'<p>No drafts.</p>';}
const beforeGoverned=render;render=function(){if(location.hash==='#governed-agent'){document.getElementById('app').innerHTML=integratedShell('governed-agent',governedPage(),model.role);bind();}else beforeGoverned();document.querySelector('.sidebar nav')?.insertAdjacentHTML('beforeend',`<a class="nav-item" href="#governed-agent">${icon('shield')}Governed agent service</a>`);};
document.addEventListener('submit',async e=>{const f=e.target;if(!['governed-connect','governed-question','governed-draft'].includes(f.id))return;e.preventDefault();const v=new FormData(f);try{if(f.id==='governed-connect'){governedToken=v.get('token');f.reset();toast('Token held in page memory; access checked on each request.');}if(f.id==='governed-question'){const r=await governedApi('query',{question:v.get('question')});document.getElementById('governed-answer').textContent=r.answer;}if(f.id==='governed-draft')governedDrafts(await governedApi('drafts',{body:v.get('body')}));}catch(err){toast(err.message);}});
document.addEventListener('click',async e=>{const t=e.target.closest('[data-governed-list],[data-governed-approve],[data-governed-audit]');if(!t)return;try{if(t.hasAttribute('data-governed-list'))governedDrafts(await governedApi('drafts'));if(t.hasAttribute('data-governed-approve')){await governedApi('approve',{id:t.dataset.governedApprove,version:Number(t.dataset.version)});governedDrafts(await governedApi('drafts'));}if(t.hasAttribute('data-governed-audit'))document.getElementById('governed-records').innerHTML='<pre style="white-space:pre-wrap">'+esc(JSON.stringify(await governedApi('audit'),null,2))+'</pre>';}catch(err){toast(err.message);}});
render();
